package app.gtdial.lab;
import android.service.notification.NotificationListenerService; import android.service.notification.StatusBarNotification; import android.app.Notification; import android.os.Bundle; import java.util.*;
/** Captures new selected notifications in memory and signals the active watch session. */
public final class NotificationForwardingService extends NotificationListenerService {
 private static final NotificationForwardingPolicy QUEUE=new NotificationForwardingPolicy(); public static NotificationRequest drainPending(){return QUEUE.poll(System.currentTimeMillis());} public static void clearPending(){QUEUE.clear();}
 @Override public void onNotificationPosted(StatusBarNotification s){if(s==null)return;Notification n=s.getNotification();if(n==null)return;android.content.SharedPreferences p=getSharedPreferences("gt_dial_preferences",MODE_PRIVATE);Bundle e=n.extras;String t=e==null?"":String.valueOf(e.getCharSequence(Notification.EXTRA_TITLE,""));String x=e==null?"":String.valueOf(e.getCharSequence(Notification.EXTRA_TEXT,""));long now=System.currentTimeMillis();NotificationRequest r=new NotificationRequest(s.getPackageName(),NotificationForwardingPolicy.bounded(t,80),NotificationForwardingPolicy.bounded(x,180),now/1000);if(NotificationForwardingPolicy.accepts(p.getBoolean("notification.forwarding.enabled",false),new HashSet<>(p.getStringSet("notification.forwarding.packages",Collections.emptySet())),getPackageName(),(n.flags&Notification.FLAG_ONGOING_EVENT)!=0,(n.flags&Notification.FLAG_GROUP_SUMMARY)!=0,r)&&QUEUE.offer(r,now)){p.edit().putLong("notification.last-captured-at",now).putString("notification.last-captured-package",r.packageName).apply();NotificationSessionBridge.signal();}}
 @Override public void onListenerDisconnected(){QUEUE.clear();super.onListenerDisconnected();}
}
